mod unicode;
use std::collections::{HashMap, HashSet};
use std::io::{self, Read};
fn has(table: &[(u32, u32)], c: char) -> bool {
    table.binary_search_by(|&(a,b)| if (c as u32)<a {std::cmp::Ordering::Greater} else if (c as u32)>b {std::cmp::Ordering::Less} else {std::cmp::Ordering::Equal}).is_ok()
}
fn lower(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut out=String::new();
    for (i,&c) in chars.iter().enumerate() {
        if c=='Σ' {
            let before=chars[..i].iter().rev().find(|&&x| "'!has(unicode::IGNORABLE,x)).is_some_and(|&x| has(unicode::CASED,x));
            let after=chars[i+1..].iter().find(|&&x| !has(unicode::IGNORABLE,x)).is_some_and(|&x| has(unicode::CASED,x));
            out.push(if before && !after {'"'ς'} else {'σ'});
        } else if let Ok(i)=unicode::LOWER.binary_search_by_key(&(c as u32), |x| x.0) {out.push_str(unicode::LOWER[i].1);} else {out.push(c);}
    }
    out
}
fn fence(line: &str) -> Option<(u8,usize,&str)> {
    let spaces=line.bytes().take_while(|&b| b==b' ').count();
    if spaces>3 {return None;}
    let rest=&line[spaces..]; let c=*rest.as_bytes().first()?;
    if c"'!=b'"'"'`'"' && c"'!=b'"'~' {return None;}
    let n=rest.bytes().take_while(|&b| b==c).count();
    (n>=3).then_some((c,n,&rest[n..]))
}
fn title(line:&str)->Option<(usize,String)> {
    let spaces=line.bytes().take_while(|&b| b==b' ').count();
    if spaces>3 {return None;}
    let rest=&line[spaces..]; let level=rest.bytes().take_while(|&b|b==b'#').count();
    if "'!(1..=6).contains(&level) {return None;}
    let rest=&rest[level..];
    if !rest.is_empty() && !rest.starts_with(['"' ','\\t']) {return None;}
    let t=rest.trim_start_matches([' ','\\t']);
    let end=t.trim_end_matches([' ','\\t']);
    let hashes=end.bytes().rev().take_while(|&b|b==b'#').count();
    let mut t=t;
    if hashes>0 {
        let prefix=&end[..end.len()-hashes];
        if prefix.is_empty() || prefix.ends_with([' ','\\t']) {t=prefix.trim_end_matches([' ','\\t']);}
    }
    let t=t.trim_matches(|c|has(unicode::SPACE,c));
    ("'!t.is_empty()).then(||(level,t.to_string()))
}
fn quote(s:&str)->String {
    let mut out=String::from("'"\\\"\");
    for c in s.chars() {match c {'\"'=>out.push_str(\"\\\\\\\"\"),'\\\\'=>out.push_str(\"\\\\\\\\\"),'\\n'=>out.push_str(\"\\\\n\"),'\\r'=>out.push_str(\"\\\\r\"),'\\t'=>out.push_str(\"\\\\t\"),'\\u{8}'=>out.push_str(\"\\\\b\"),'\\u{c}'=>out.push_str(\"\\\\f\"), c if c<' '=>out.push_str(&format"'!("'"\\\\u{:04x}\",c as u32)), c=>out.push(c)}}
    out.push('\"');out
}
fn fail(message:&str,code:i32)->"'! {eprintln!("mdtoc: error: {message}");std::process::exit(code)}
fn level(s:&str)->usize {
    let s=s.trim_matches(|c|has(unicode::SPACE,c));
    let s=s.strip_prefix('"'+').unwrap_or(s);
    let s=s.replace('_',\"\");
    match s.parse::<usize>() {Ok(n) if (1..=6).contains(&n)=>n,_=>fail(\"invalid level\",2)}
}
fn main() {
    let mut min=1;let mut max=6;let mut json=false;let mut numbered=false;let mut file=None;let mut end=false;
    let mut args=std::env::args().skip(1);
    while let Some(arg)=args.next() {
        if "'!end && arg=="--" {end=true;continue;}
        if !end && (arg=="--help" || arg=="-h") {println!("mdtoc [FILE] [--min-level N] [--max-level N] [--json] [--numbered]");return;}
        if !end && arg=="--json" {json=true;continue;}
        if !end && arg=="--numbered" {numbered=true;continue;}
        if !end && (arg=="--min-level" || arg=="--max-level" || arg.starts_with("--min-level=") || arg.starts_with("--max-level=")) {
            let (key,value)=if let Some((k,v))=arg.split_once('"'=') {(k.to_string(),v.to_string())} else {(arg,args.next().unwrap_or_else(||fail(\"missing level\",2)))};
            let n=level(&value);if key==\"--min-level\" {min=n;} else {max=n;}continue;
        }
