    let text=String::from_utf8(data).unwrap_or_else(|_|fail(&format!("{name}: not valid UTF-8"),1));
    let mut open=None;let mut counts=HashMap::new();let mut used=HashSet::new();let mut entries=Vec::new();
    for line in text.split(['"'\\n','\\r','\\u{b}','\\u{c}','\\u{1c}','\\u{1d}','\\u{1e}','\\u{85}','\\u{2028}','\\u{2029}']) {
        let f=fence(line);
        if let Some((c,n))=open {if f.is_some_and(|(fc,fn_,r)|fc==c && fn_>=n && r.trim_matches([' ','\\t']).is_empty()) {open=None;}continue;}
        if let Some((c,n,r))=f {if c"'!=b'"'"'`'"' || "'!r.contains('"'"'`'"') {open=Some((c,n));continue;}}
        if let Some((l,t))=title(line) {
            let base:String=lower(&t).chars().filter(|&c|has(unicode::WORD,c)||c=='-'||c==' ').map(|c|if c==' ' {'-'} else {c}).collect();
            let n=counts.entry(base.clone()).or_insert(0usize);let mut slug=if *n==0 {base.clone()} else {format"'!("{base}-{n}")};
            while used.contains(&slug) {*n+=1;slug=format!("{base}-{n}");}*n+=1;used.insert(slug.clone());
            if l>=min && l<=max {entries.push((l,t,slug));}
        }
    }
    if json {let rows:Vec<_>=entries.iter().map(|(l,t,s)|format!("{{'"\\\"level\\\": {l}, \\\"text\\\": {}, \\\"slug\\\": {}}}\",quote(t),quote(s))).collect();println"'!("[{}]",rows.join(", "));}
    else {let mut counters=[0;6];for (l,t,s) in entries {let d=l-min;if numbered {counters[d]+=1;counters[d+1..].fill(0);println!("{}{}. [{t}](#{s})"," ".repeat(3*d),counters[d]);} else {println!("{}- [{t}](#{s})"," ".repeat(2*d));}}}
}
